using System.Globalization;
using System.Text;
using PdfSharp.Drawing;
using PdfSharp.Pdf;
using PdfSharp.Pdf.Advanced;
using PdfSharp.Pdf.Content;
using PdfSharp.Pdf.Content.Objects;
using PdfSharp.Pdf.IO;
using SharpDocument = PdfSharp.Pdf.PdfDocument;

namespace NT.AvaloniaControl.PdfViewer.Editing;

/// <summary>
/// The bounded structural bridge for appearances generated by PDFium. It does not parse arbitrary
/// page content or implement a general PDF editor. Each call owns a new PDFsharp document because
/// its save operation consumes that document, including when writing fails.
/// </summary>
internal static class PdfStructureWriter
{
    internal const int MaximumDocumentBytes = 256 * 1024 * 1024;
    internal const int MaximumAppearanceBytes = 64 * 1024 * 1024;
    internal const int MaximumAppearanceContentBytes = 4 * 1024 * 1024;
    internal const int MaximumTextLength = 16_384;
    private const string IdPrefix = "NT.FreeText.";

    internal static byte[] ApplyFreeText(byte[] input, int pageIndex, double left, double bottom,
        double width, double height, string text, byte[] appearancePdf, Guid annotationId, bool update,
        CancellationToken cancellationToken)
    {
        ValidateBytes(input, MaximumDocumentBytes, nameof(input));
        ValidateBytes(appearancePdf, MaximumAppearanceBytes, nameof(appearancePdf));
        ArgumentNullException.ThrowIfNull(text);
        if (text.Length is 0 or > MaximumTextLength || text.Contains('\0'))
            throw new ArgumentException($"Text must contain 1 to {MaximumTextLength} UTF-16 code units and no null characters.", nameof(text));
        if (annotationId == Guid.Empty) throw new ArgumentException("A non-empty annotation ID is required.", nameof(annotationId));
        ValidateRectangle(left, bottom, width, height);
        cancellationToken.ThrowIfCancellationRequested();

        using var inputStream = new MemoryStream(input, writable: false);
        using var target = PdfReader.Open(inputStream, PdfDocumentOpenMode.Modify);
        ValidatePageIndex(target, pageIndex);
        var name = IdPrefix + annotationId.ToString("D");
        var annotation = FindAnnotation(target, pageIndex, name, cancellationToken);
        if (update && annotation is null) throw new KeyNotFoundException("The FreeText annotation does not exist on the requested page.");
        if (!update && annotation is not null) throw new InvalidOperationException("The annotation ID already exists.");

        using var appearanceStream = new MemoryStream(appearancePdf, writable: false);
        using var scratch = PdfReader.Open(appearanceStream, PdfDocumentOpenMode.Import);
        if (scratch.PageCount != 1) throw new InvalidDataException("The native appearance must contain exactly one page.");
        var sourcePage = scratch.Pages[0];
        var sourceAnnotations = sourcePage.Elements.GetArray("/Annots");
        if (sourceAnnotations?.Elements.Count != 1 || Dereference(sourceAnnotations.Elements[0]) is not PdfDictionary stamp
            || stamp.Elements.GetName("/Subtype") != "/Stamp")
            throw new InvalidDataException("The native appearance must contain exactly one Stamp annotation.");
        var sourceAppearance = stamp.Elements.GetDictionary("/AP")?.Elements.GetDictionary("/N")
            ?? throw new InvalidDataException("The Stamp has no normal appearance stream.");
        if (sourceAppearance.Stream is null) throw new InvalidDataException("The normal appearance is not a stream.");
        var sourceResources = sourceAppearance.Elements.GetDictionary("/Resources")
            ?? throw new InvalidDataException("The appearance has no resources.");

        // AddPage imports page resources/content through PDFsharp's reference map. Promote the Stamp
        // AP into those slots first; relying on annotation import alone loses its resource closure.
        sourcePage.Elements["/Resources"] = ReferenceOrObject(sourceResources);
        sourcePage.Elements["/Contents"] = ReferenceOrObject(sourceAppearance);
        sourcePage.Elements.Remove("/Annots");
        var importedPage = target.AddPage(sourcePage);
        var appearance = importedPage.Elements.GetDictionary("/Contents")
            ?? throw new InvalidDataException("The appearance stream could not be imported.");
        var resources = importedPage.Elements.GetDictionary("/Resources")
            ?? throw new InvalidDataException("The appearance resources could not be imported.");
        appearance.Elements["/Resources"] = ReferenceOrObject(resources);
        var defaultAppearance = NormalizeAppearance(target, appearance, resources, annotationId, width, height, cancellationToken);
        target.Pages.RemoveAt(target.PageCount - 1);
        cancellationToken.ThrowIfCancellationRequested();

        var page = target.Pages[pageIndex];
        RegisterPageFonts(target, page, resources.Elements.GetDictionary("/Font")!, "/NTFT_" + annotationId.ToString("N") + "_");
        if (annotation is null)
        {
            annotation = new PdfDictionary(target);
            target.Internals.AddObject(annotation);
            var annotations = page.Elements.GetArray("/Annots");
            if (annotations is null)
            {
                annotations = new PdfArray(target);
                page.Elements["/Annots"] = annotations;
            }
            annotations.Elements.Add(annotation.Reference!);
        }
        annotation.Elements.SetName("/Type", "/Annot");
        annotation.Elements.SetName("/Subtype", "/FreeText");
        annotation.Elements.SetString("/NM", name);
        annotation.Elements["/Contents"] = new PdfString(text, PdfStringEncoding.Unicode);
        annotation.Elements.SetRectangle("/Rect", new PdfRectangle(new XPoint(left, bottom), new XSize(width, height)));
        annotation.Elements.SetInteger("/F", annotation.Elements.GetInteger("/F") | 4);
        annotation.Elements.SetString("/DA", defaultAppearance);
        annotation.Elements.SetInteger("/Q", 0);
        annotation.Elements.SetDateTime("/M", DateTime.UtcNow);
        annotation.Elements["/P"] = page.Reference!;
        annotation.Elements["/DR"] = ReferenceOrObject(resources);
        annotation.Elements.Remove("/RC"); // An old rich-text value must not override the new Contents.
        var appearances = new PdfDictionary(target);
        if (appearance.Reference is null) target.Internals.AddObject(appearance);
        appearances.Elements["/N"] = appearance.Reference!;
        annotation.Elements["/AP"] = appearances;

        cancellationToken.ThrowIfCancellationRequested();
        using var output = new MemoryStream();
        target.Save(output, closeStream: false);
        cancellationToken.ThrowIfCancellationRequested();
        if (output.Length > MaximumDocumentBytes) throw new InvalidDataException("The edited PDF exceeds the 256 MiB structural writer limit.");
        var bytes = output.ToArray();
        var stored = ReadFreeText(bytes, pageIndex);
        if (stored.Count(item => item.Id == annotationId && item.Text == text) != 1)
            throw new InvalidDataException("The serialized FreeText annotation failed its structural reopen check.");
        return bytes;
    }

    internal static IReadOnlyList<PdfStoredFreeText> ReadFreeText(byte[] input, int pageIndex)
    {
        ValidateBytes(input, MaximumDocumentBytes, nameof(input));
        using var stream = new MemoryStream(input, writable: false);
        using var document = PdfReader.Open(stream, PdfDocumentOpenMode.Import);
        ValidatePageIndex(document, pageIndex);
        var annotations = document.Pages[pageIndex].Elements.GetArray("/Annots");
        if (annotations is null) return [];
        var result = new List<PdfStoredFreeText>();
        var ids = new HashSet<Guid>();
        foreach (var item in annotations.Elements)
        {
            if (Dereference(item) is not PdfDictionary annotation || annotation.Elements.GetName("/Subtype") != "/FreeText") continue;
            var name = annotation.Elements.GetString("/NM");
            if (!name.StartsWith(IdPrefix, StringComparison.Ordinal) || !Guid.TryParseExact(name[IdPrefix.Length..], "D", out var id)) continue;
            if (!ids.Add(id)) throw new InvalidDataException("The page contains duplicate NT FreeText IDs.");
            var rect = annotation.Elements.GetRectangle("/Rect");
            result.Add(new PdfStoredFreeText(id, pageIndex, rect.X1, rect.Y1, rect.Width, rect.Height, annotation.Elements.GetString("/Contents")));
        }
        return result;
    }

    private static string NormalizeAppearance(SharpDocument document, PdfDictionary appearance, PdfDictionary resources,
        Guid id, double width, double height, CancellationToken cancellationToken)
    {
        var content = appearance.Stream.UnfilteredValue;
        if (content.Length is 0 or > MaximumAppearanceContentBytes)
            throw new InvalidDataException("The native appearance content must contain 1 byte to 4 MiB.");
        var sequence = ContentReader.ReadContent(content);
        var fonts = resources.Elements.GetDictionary("/Font")
            ?? throw new InvalidDataException("The native appearance has no font resources.");
        var prefix = "/NTFT_" + id.ToString("N") + "_";
        var fontMap = new Dictionary<string, string>(StringComparer.Ordinal);
        var registeredFonts = new PdfDictionary(document);
        string? defaultAppearance = null;
        foreach (var item in sequence)
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (item is not COperator { Name: "Tf" } operation) continue;
            if (operation.Operands.Count != 2 || operation.Operands[0] is not CName fontName)
                throw new InvalidDataException("A native Tf operator is malformed.");
            var size = operation.Operands[1] switch { CInteger integer => integer.Value, CReal real => real.Value, _ => double.NaN };
            if (!double.IsFinite(size) || size <= 0) throw new InvalidDataException("The appearance font size is invalid.");
            var original = fontName.Name.StartsWith('/') ? fontName.Name : "/" + fontName.Name;
            var font = fonts.Elements.GetDictionary(original)
                ?? throw new InvalidDataException("The appearance refers to an undefined font resource.");
            RequireEmbeddedFont(font);
            if (!fontMap.TryGetValue(original, out var renamed))
            {
                renamed = prefix + fontMap.Count.ToString(CultureInfo.InvariantCulture);
                fontMap.Add(original, renamed);
                registeredFonts.Elements[renamed] = ReferenceOrObject(font);
            }
            operation.Operands[0] = new CName(renamed);
            defaultAppearance ??= renamed + " " + Number(size) + " Tf 0 g";
        }
        if (defaultAppearance is null) throw new InvalidDataException("The native appearance contains no font selection.");
        resources.Elements["/Font"] = registeredFonts;
        RegisterDefaultFonts(document, registeredFonts, prefix);

        var bounds = appearance.Elements.GetRectangle("/BBox");
        var matrix = appearance.Elements.GetMatrix("/Matrix");
        var corners = new[] { new XPoint(bounds.X1, bounds.Y1), new XPoint(bounds.X1, bounds.Y2), new XPoint(bounds.X2, bounds.Y1), new XPoint(bounds.X2, bounds.Y2) };
        var transformed = corners.Select(matrix.Transform).ToArray();
        var minX = transformed.Min(point => point.X);
        var minY = transformed.Min(point => point.Y);
        var extentX = transformed.Max(point => point.X) - minX;
        var extentY = transformed.Max(point => point.Y) - minY;
        if (!double.IsFinite(extentX) || !double.IsFinite(extentY) || extentX <= 0 || extentY <= 0)
            throw new InvalidDataException("The native appearance bounds or matrix are invalid.");
        var scaleX = width / extentX;
        var scaleY = height / extentY;
        var transform = $"q\n{Number(scaleX)} 0 0 {Number(scaleY)} {Number(-minX * scaleX)} {Number(-minY * scaleY)} cm\n" +
            $"{Number(matrix.M11)} {Number(matrix.M12)} {Number(matrix.M21)} {Number(matrix.M22)} {Number(matrix.OffsetX)} {Number(matrix.OffsetY)} cm\n";
        var normalized = Encoding.ASCII.GetBytes(transform).Concat(sequence.ToContent()).Concat("\nQ\n"u8.ToArray()).ToArray();
        appearance.Stream.Value = normalized;
        appearance.Elements.Remove("/Filter");
        appearance.Elements.Remove("/DecodeParms");
        appearance.Elements.SetInteger("/Length", normalized.Length);
        appearance.Elements.SetName("/Type", "/XObject");
        appearance.Elements.SetName("/Subtype", "/Form");
        appearance.Elements.SetInteger("/FormType", 1);
        appearance.Elements.SetRectangle("/BBox", new PdfRectangle(new XPoint(0, 0), new XSize(width, height)));
        appearance.Elements.SetMatrix("/Matrix", XMatrix.Identity);
        return defaultAppearance;
    }

    private static void RegisterDefaultFonts(SharpDocument document, PdfDictionary fonts, string prefix)
    {
        var catalog = document.Internals.Catalog;
        var form = catalog.Elements.GetDictionary("/AcroForm");
        if (form is null)
        {
            form = new PdfDictionary(document);
            document.Internals.AddObject(form);
            form.Elements["/Fields"] = new PdfArray(document);
            catalog.Elements["/AcroForm"] = form.Reference!;
        }
        var defaults = form.Elements.GetDictionary("/DR");
        if (defaults is null) form.Elements["/DR"] = defaults = new PdfDictionary(document);
        var documentFonts = defaults.Elements.GetDictionary("/Font");
        if (documentFonts is null) defaults.Elements["/Font"] = documentFonts = new PdfDictionary(document);
        foreach (var key in documentFonts.Elements.KeyNames.Where(key => key.Value.StartsWith(prefix, StringComparison.Ordinal)).ToArray())
            documentFonts.Elements.Remove(key.Value);
        foreach (var font in fonts.Elements) documentFonts.Elements[font.Key] = font.Value;
    }

    private static void RegisterPageFonts(SharpDocument document, PdfPage page, PdfDictionary fonts, string prefix)
    {
        // A page may share its inherited Resources/Font dictionaries with other pages. Copy just the
        // containers before adding aliases, keeping the actual font object references unchanged.
        var originalResources = page.Elements.GetDictionary("/Resources");
        var resources = new PdfDictionary(document);
        if (originalResources is not null)
            foreach (var resource in originalResources.Elements) resources.Elements[resource.Key] = resource.Value;
        var originalFonts = originalResources?.Elements.GetDictionary("/Font");
        var pageFonts = new PdfDictionary(document);
        if (originalFonts is not null)
            foreach (var font in originalFonts.Elements)
                if (!font.Key.StartsWith(prefix, StringComparison.Ordinal)) pageFonts.Elements[font.Key] = font.Value;
        foreach (var font in fonts.Elements) pageFonts.Elements[font.Key] = font.Value;
        resources.Elements["/Font"] = pageFonts;
        page.Elements["/Resources"] = resources;
    }

    private static void RequireEmbeddedFont(PdfDictionary font)
    {
        if (font.Elements.GetName("/Subtype") == "/Type0")
            font = font.Elements.GetArray("/DescendantFonts")?.Elements.GetDictionary(0)
                ?? throw new InvalidDataException("The Type0 font has no descendant font.");
        var descriptor = font.Elements.GetDictionary("/FontDescriptor");
        if (descriptor is null || !new[] { "/FontFile", "/FontFile2", "/FontFile3" }
            .Any(key => descriptor.Elements.GetDictionary(key)?.Stream is not null))
            throw new InvalidDataException("FreeText appearances must embed their font; system fallback is not supported.");
    }

    private static PdfDictionary? FindAnnotation(SharpDocument document, int pageIndex, string name, CancellationToken token)
    {
        PdfDictionary? match = null;
        for (var index = 0; index < document.PageCount; index++)
        {
            token.ThrowIfCancellationRequested();
            var annotations = document.Pages[index].Elements.GetArray("/Annots");
            if (annotations is null) continue;
            foreach (var item in annotations.Elements)
            {
                if (Dereference(item) is not PdfDictionary annotation || annotation.Elements.GetString("/NM") != name) continue;
                if (index != pageIndex || match is not null || annotation.Elements.GetName("/Subtype") != "/FreeText")
                    throw new InvalidDataException("The annotation ID is duplicated, belongs to another page, or is not FreeText.");
                match = annotation;
            }
        }
        return match;
    }

    private static void ValidateBytes(byte[] bytes, int maximum, string name)
    {
        ArgumentNullException.ThrowIfNull(bytes, name);
        if (bytes.Length == 0 || bytes.Length > maximum) throw new ArgumentException($"PDF data must contain 1 to {maximum} bytes.", name);
    }

    private static void ValidatePageIndex(SharpDocument document, int pageIndex)
    {
        if ((uint)pageIndex >= (uint)document.PageCount) throw new ArgumentOutOfRangeException(nameof(pageIndex));
    }

    private static void ValidateRectangle(double left, double bottom, double width, double height)
    {
        if (!double.IsFinite(left) || !double.IsFinite(bottom) || !double.IsFinite(width) || !double.IsFinite(height)
            || width <= 0 || height <= 0 || Math.Abs(left) > 1_000_000 || Math.Abs(bottom) > 1_000_000 || width > 1_000_000 || height > 1_000_000)
            throw new ArgumentOutOfRangeException(nameof(width), "A finite positive PDF rectangle within one million points is required.");
    }

    private static PdfItem ReferenceOrObject(PdfObject item) => (PdfItem?)item.Reference ?? item;
    private static PdfItem? Dereference(PdfItem? item) => item is PdfReference reference ? reference.Value : item;
    private static string Number(double value) => value.ToString("0.##########", CultureInfo.InvariantCulture);
}

internal sealed record PdfStoredFreeText(Guid Id, int PageIndex, double Left, double Bottom, double Width, double Height, string Text);
